def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--negative-controls", action="store_true")
    args = parser.parse_args()
    sources = dict(SOURCES)
    marker = '  System.out.println("EDITOR EVIDENCE RESULT "'
    assert TEST.count(marker) == 1
    sources["ls/augment/com/hook/TestEditorEvidence.java"] = TEST.replace(marker, DEVICE_EVIDENCE_TEST + marker)
    production = PASTE["MODELS"][:-1] + ["hook/AtomicWorkbenchImeHook.java", "hook/AtomicWorkbenchEditorEvidenceHook.java", "hook/AtomicWorkbenchDisplayDeviceEvidence.java"]
    with tempfile.TemporaryDirectory(prefix="lsa-editor-evidence-") as directory:
        SUPPORT["compile_run"](Path(directory), sources, production, "ls.augment.com.hook.TestEditorEvidence")
    module = (SUPPORT["SRC"] / "hook/AugmentModule.java").read_text(encoding="utf-8")
    readiness = module.split("private boolean systemServerHooksReady()", 1)[1].split("\n    }", 1)[0]
    assert "AtomicWorkbenchEditorEvidenceHook" not in readiness
    assert "AtomicWorkbenchFocusWindowHook.isInstalled()" in readiness
    assert "AtomicWorkbenchEditorEvidenceHook.install(this, classLoader)" in module
    print("PASS paste evidence remains optional to global readiness; P0 focus guard remains required")
    if args.negative_controls:
        negatives(sources, production)


def negatives(sources, production):
    mutations = [
        ("AtomicWorkbenchImeHook.java", "identity != null && identity.pid == rootPid", "identity != null", "unsafe editor evidence authorized"),
        ("AtomicWorkbenchEditorEvidenceHook.java", "!input.same(input(ims, r, first))", "false", "unsafe editor evidence authorized"),
        ("AtomicWorkbenchEditorEvidenceHook.java", "|| password(in.type)", "", "password metadata escaped system evidence gate"),
        ("AtomicWorkbenchEditorEvidenceHook.java", "|| displayDeviceEvidence == null || !displayDeviceEvidence.ownsContentOnly(service,display)", "", "unsafe editor evidence authorized"),
        ('AtomicWorkbenchEditorEvidenceHook.java', 'return flags instanceof Integer && (((Integer) flags) & ~BINDER_SYNC_METADATA_FLAGS) == 0;', 'return flags instanceof Integer;', 'oneway evidence reached original or generated reply'),
    ]
    for filename, before, after, expected in mutations:
        source = (SUPPORT["SRC"] / "hook" / filename).read_text(encoding="utf-8")
        assert source.count(before) == 1, filename
        with tempfile.TemporaryDirectory(prefix="lsa-editor-negative-") as directory:
            work = Path(directory); files = []; all_sources = dict(sources)
            all_sources.update({"ls/augment/com/" + name: (SUPPORT["SRC"] / name).read_text(encoding="utf-8") for name in production})
            all_sources["ls/augment/com/hook/" + filename] = source.replace(before, after)
            for name, value in all_sources.items():
                path = work / name; path.parent.mkdir(parents=True, exist_ok=True); path.write_text(value, encoding="utf-8"); files.append(str(path))
            compiled = subprocess.run([SUPPORT["JAVAC"], "-encoding", "UTF-8", "-d", str(work / "classes"), *files], capture_output=True, text=True, encoding="utf-8", env=SUPPORT["ENV"], timeout=30)
            if compiled.returncode: raise AssertionError(compiled.stdout + compiled.stderr)
            result = subprocess.run([SUPPORT["JAVA"], "-cp", str(work / "classes"), "ls.augment.com.hook.TestEditorEvidence"], capture_output=True, text=True, encoding="utf-8", env=SUPPORT["ENV"], timeout=30)
            if result.returncode == 0 or expected not in result.stdout + result.stderr: raise AssertionError(result.stdout + result.stderr)
            print("PASS editor-evidence negative control: " + filename + " / " + before)


if __name__ == "__main__":
    main()
